    request<{ id: string; root: string; name: string }[]>(connection, "/api/projects/discovered", { signal: controller.signal })
      .then((items) => { if (!controller.signal.aborted) setDiscovery({ key: identity, items: Array.isArray(items) ? items : [], error: "" }); })
      .catch((error) => { if (!controller.signal.aborted) setDiscovery({ key: identity, items: [], error: errorMessage(error) }); });
    return () => controller.abort();
  }, [identity, connection?.bearer]);
  const workspaceDialogId = useId();
  const projectContentId = useId();
  const workspaceRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const currentRef = useRef<HTMLButtonElement>(null);
  const projectContent = useRef<HTMLDivElement>(null);
  const workspaceProject = currentWorkspaceProject(connected ? workspaceId : "", connected ? workspaceRoot : "");
  const workspacePath = connected ? workspaceProject.path || workspaceId : "";
  const workspaceName = workspaceProject.name;
  const projectCanCollapse = active && !compactViewport;

  useEffect(() => { if (!active) setWorkspaceOpen(false); }, [active]);
  useEffect(() => {
    const media = window.matchMedia("(max-width: 760px)");
    const update = () => setCompactViewport(media.matches);
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  useLayoutEffect(() => {
    const element = projectContent.current;
    if (!element) return;
    element.toggleAttribute("inert", projectCanCollapse && !projectExpanded);
    const finish = () => { element.style.height = !projectCanCollapse || projectExpanded ? "auto" : "0px"; element.style.opacity = !projectCanCollapse || projectExpanded ? "1" : "0"; };
    if (!projectCanCollapse || window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    element.style.height = `${element.getBoundingClientRect().height}px`;
    void element.offsetHeight;
    let timeout = 0;
    const frame = requestAnimationFrame(() => {
      element.style.height = projectExpanded ? `${element.scrollHeight}px` : "0px";
      element.style.opacity = projectExpanded ? "1" : "0";
      timeout = window.setTimeout(finish, 200);
    });
    const transitioned = (event: TransitionEvent) => { if (event.target === element && event.propertyName === "height") finish(); };
    element.addEventListener("transitionend", transitioned);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timeout); element.removeEventListener("transitionend", transitioned); };
  }, [projectCanCollapse, projectExpanded]);

  const closeWorkspace = useCallback(() => {
    setWorkspaceOpen(false);
    triggerRef.current?.focus();
  }, []);
  useLayoutEffect(() => {
    const element = dialogRef.current;
    if (!element) return;
    element.toggleAttribute("inert", !workspaceOpen);
    const finish = () => { element.style.height = workspaceOpen ? "auto" : "0px"; element.style.opacity = workspaceOpen ? "1" : "0"; };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { finish(); return; }
    element.style.height = `${element.getBoundingClientRect().height}px`;
    void element.offsetHeight;
    const frame = requestAnimationFrame(() => { element.style.height = workspaceOpen ? `${element.scrollHeight}px` : "0px"; element.style.opacity = workspaceOpen ? "1" : "0"; });
    const timer = window.setTimeout(finish, 180);
    return () => { cancelAnimationFrame(frame); window.clearTimeout(timer); };
  }, [workspaceOpen]);

  useEffect(() => {
    if (!workspaceOpen) return;
    (currentRef.current || dialogRef.current)?.focus();

    function handlePointerDown(event: PointerEvent) {
      if (event.target instanceof Node && !workspaceRef.current?.contains(event.target)) closeWorkspace();
    }
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.preventDefault();
        closeWorkspace();
      }
    }
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [workspaceOpen, closeWorkspace]);

  return <div className="sidebar-panel" data-workspace-panel="">
    <div className="workspace-selector-wrap" ref={workspaceRef}>
      <button
        ref={triggerRef}
        type="button"
        className={`workspace-selector${workspaceOpen ? " is-open" : ""}`}
        aria-label="选择工作空间"
        aria-haspopup="dialog"
        aria-expanded={workspaceOpen}
        aria-controls={workspaceDialogId}
        title={workspacePath || undefined}
        onClick={() => workspaceOpen ? closeWorkspace() : setWorkspaceOpen(true)}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            if (workspaceOpen) (currentRef.current || dialogRef.current)?.focus();
            else setWorkspaceOpen(true);
          }
        }}
      >
        <span className="workspace-selector-name">FORGE</span>
        <svg className="workspace-selector-chevron" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m5 6 3 3 3-3" /></svg>
      </button>

      <div
        id={workspaceDialogId}
        ref={dialogRef}
        className="workspace-menu"
        role="dialog"
        aria-label="工作空间选择"
        aria-hidden={!workspaceOpen}
        tabIndex={-1}
        onKeyDown={(event) => {
          if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
            event.preventDefault();
            (currentRef.current || dialogRef.current)?.focus();
          }
          if (event.key === "Tab") closeWorkspace();
        }}
      >
        <p className="workspace-menu-label">当前工作空间</p>
        {connected ? <button
          ref={currentRef}
          type="button"
          className="workspace-menu-current"
          aria-label="使用当前工作空间"
          aria-current="true"
          onClick={closeWorkspace}
        >
          <FolderIcon />
          <span className="workspace-menu-copy"><strong>{workspaceName}</strong><span className="workspace-menu-path">{workspacePath || "工作空间路径暂不可用"}</span></span>
          <svg className="workspace-menu-check" viewBox="0 0 20 20" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m5 10 3.5 3.5L15 7" /></svg>
        </button> : <p className="workspace-menu-empty">连接后显示工作空间</p>}
      </div>
    </div>
    {topNavigation}
    <div className="sidebar-scroll">
      <SidebarGroup label="置顶"><p className="sidebar-empty">暂无置顶项</p></SidebarGroup>
      <section className="sidebar-project-group" data-project-key={workspaceProject.key} data-project-source="workspace">
        <h2 className="sidebar-section-label">项目</h2>
        <button type="button" className="sidebar-project-toggle" aria-label={`${projectExpanded ? "收起" : "展开"}项目 ${workspaceName}`} aria-expanded={projectExpanded} aria-controls={projectContentId} title={workspacePath || undefined} onClick={() => setProjectExpanded((expanded) => !expanded)} onKeyDown={(event) => {
          if (event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229 || event.altKey || event.ctrlKey || event.metaKey) return;
          if (event.key === "ArrowLeft") { event.preventDefault(); setProjectExpanded(false); }
          if (event.key === "ArrowRight") { event.preventDefault(); setProjectExpanded(true); }
          if (event.key === "ArrowDown" && projectExpanded) { event.preventDefault(); projectContent.current?.querySelector<HTMLButtonElement>("button")?.focus(); }
        }}>
          <svg className="project-chevron" data-chevron viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg>
          <FolderIcon /><span>{workspaceName}</span>
        </button>
        <div ref={projectContent} id={projectContentId} className="sidebar-project-content" aria-hidden={projectCanCollapse && !projectExpanded}>{navigation}</div>
        {discovery.key === identity && discovery.items.filter((item) => item.root.replace(/\\/g, "/").toLowerCase() !== workspaceRoot.replace(/\\/g, "/").toLowerCase()).map((item) => <div className="discovered-project" key={item.id} title={`${item.root}\n已发现的项目；不授予目录访问权限。`}><FolderIcon /><span>{item.name}</span><small>已发现</small></div>)}
        {discovery.key === identity && discovery.error && <p className="sidebar-empty" title={discovery.error}>项目发现暂不可用</p>}
      </section>
      <SidebarGroup label="最近"><p className="sidebar-empty">当前工作空间使用一条长期对话</p></SidebarGroup>
    </div>
    <div className="sidebar-connection">{children}</div>
    <div className="sidebar-footer">{footer}</div>
  </div>;
}

import { useEffect, useRef, useState } from "react";
import { request, type Connection } from "../api";
import type { WorkerRun } from "../ConversationRuntime";
import { errorMessage } from "../logic";
import { statusLabel } from "../presentation";
import { teamReassignmentProposal, userQuestTransitions } from "../questControls";
import { asRecord, rows, text, type Quest, type Row } from "../workspaceTypes";
import { TechnicalDetails } from "./WorkspacePanels";

interface QuestData { identity: string; history: Row[]; teams: Row[]; workers: Row[]; preview: Row[]; loading: boolean; error: string }

/** Advanced task operations remain attached to the conversation's task drawer. */
export default function QuestControls({ connection, quest, plan, runs, blocked, onAction }: {
  connection: Connection | null; quest: Quest; plan: Row | null; runs: WorkerRun[]; blocked: boolean;
  onAction: (path: string, body?: unknown) => Promise<unknown>;
}) {
  const [open, setOpen] = useState(false), [refresh, setRefresh] = useState(0);
  const identity = connection ? `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}|${quest.id}` : "";
  const current = useRef(identity); current.current = identity;
  const [data, setData] = useState<QuestData>({ identity: "", history: [], teams: [], workers: [], preview: [], loading: false, error: "" });
  const [error, setError] = useState("");
  const [role, setRole] = useState(""), [model, setModel] = useState("");
  const [runId, setRunId] = useState(""), [reason, setReason] = useState(""), [teamId, setTeamId] = useState("");
  const [strategy, setStrategy] = useState("greedy");
  const [remaining, setRemaining] = useState(false), [expansion, setExpansion] = useState("");
  const visible = data.identity === identity ? data : { history: [], teams: [], workers: [], preview: [], loading: open, error: "" };
  const questPath = `/api/quests/${encodeURIComponent(quest.id)}`;
  const terminal = ["completed", "failed", "cancelled", "rejected"].includes(quest.status);
  const disabled = blocked || !connection;
  const canReplan = !!plan && ["approved", "paused"].includes(text(plan.status)) && ["approved", "queued", "paused", "blocked", "needs_input", "running"].includes(quest.status);
  const currentRuns = runs.filter((run) => run.quest_id === quest.id);
  useEffect(() => {
    if (!open || !connection) return;
    const pending = new AbortController(); let active = true;
    setData({ identity, history: [], teams: [], workers: [], preview: [], loading: true, error: "" });
    const read = (path: string) => request<unknown>(connection, path, { signal: pending.signal }).then(value => ({ value, error: "" })).catch(error => ({ value: null, error: errorMessage(error) }));
    void Promise.all([read(`${questPath}/plan/history`), read(`${questPath}/teams`), read(questPath), read("/api/team/preview")]).then(([history, teams, detail, preview]) => {
      if (!active || current.current !== identity) return;
      setData({ identity, history: rows(history.value), teams: rows(teams.value), workers: rows(asRecord(detail.value).workers), preview: rows(preview.value), loading: false,
        error: [history.error, teams.error, detail.error, preview.error].filter(Boolean).join("；") });
    });
    return () => { active = false; pending.abort(); };
  }, [identity, connection?.bearer, open, quest.version, refresh]);
  const act = async (label: string, path: string, body?: unknown) => {
    if (disabled || !window.confirm(`${label}？\n任务：${quest.title}\n任务版本：${quest.version}`)) return;
    const submittedIdentity = identity;
    setError("");
    await onAction(path, body);
    if (current.current === submittedIdentity) setRefresh(value => value + 1);
  };
  const version = { expected_version: quest.version };
  const planActions = [
    ...(plan?.status === "approved" && ["approved", "queued", "running"].includes(quest.status) ? [{ action: "pause", label: "暂停计划" }] : []),
    ...(plan?.status === "paused" && quest.status === "paused" ? [{ action: "resume", label: "恢复计划" }] : []),
    ...(plan && ["proposed", "approved", "paused"].includes(text(plan.status)) && !terminal && quest.status !== "reviewing" ? [{ action: "cancel", label: "取消计划" }] : []),
    ...(plan && quest.status === "failed" ? [{ action: "retry", label: "为失败任务创建重试提案" }] : []),
  ];
  return <details className="settings-disclosure quest-controls" open={open} onToggle={event => setOpen(event.currentTarget.open)}>
    <summary>任务操作与历史</summary>
    <div className="settings-disclosure-body">
      <div className="button-row">{planActions.map(item => <button type="button" className="button" key={item.action} disabled={disabled} onClick={() => void act(item.label, `${questPath}/plan/control`, { ...version, action: item.action })}>{item.label}</button>)}</div>
      {!terminal && <label className="field-label">任务优先级<select value={typeof quest.priority === "number" ? quest.priority : ""} disabled={disabled} onChange={event => void act("调整优先级", `${questPath}/priority`, { ...version, priority: Number(event.target.value) })}><option value="" disabled>未记录</option>{[1, 2, 3, 4, 5].map(value => <option key={value} value={value}>{value}{value === 1 ? " · 最高" : value === 5 ? " · 最低" : ""}</option>)}</select></label>}
      {userQuestTransitions(quest.status).length > 0 && <label className="field-label">调整任务状态<select value="" disabled={disabled} onChange={event => void act(`将任务设为${statusLabel(event.target.value)}`, `${questPath}/transition`, { ...version, status: event.target.value })}><option value="">选择状态…</option>{userQuestTransitions(quest.status).map(value => <option value={value} key={value}>{statusLabel(value)}</option>)}</select></label>}
      {!terminal && <form onSubmit={event => { event.preventDefault(); void act(remaining ? "重新生成剩余计划" : "生成计划", `${questPath}/plan/generate`, { ...version, remaining_dag: remaining, ...(remaining && expansion.trim() ? { expansion_parent: expansion.trim() } : {}) }); }}>
        <label className="check-label"><input type="checkbox" checked={remaining} onChange={event => setRemaining(event.target.checked)} />保留已完成节点，重新规划剩余工作</label>
        {remaining && <label className="field-label">展开节点（可选）<input value={expansion} onChange={event => setExpansion(event.target.value)} placeholder="计划中的节点键" /></label>}
        <button type="submit" className="button" disabled={disabled || (remaining ? !canReplan : !["proposed", "awaiting_approval"].includes(quest.status))}>生成计划</button>
      </form>}
      {visible.loading && <p className="notice" role="status">正在读取任务历史…</p>}
      {visible.error && <p className="notice error" role="alert">{visible.error}</p>}
      <section><h3>计划历史</h3>{!visible.loading && !visible.history.length && <p className="notice">暂无计划历史</p>}{visible.history.map(item => <div className="plan-node" key={text(item.id)}><strong>版本 {text(item.revision)} · {statusLabel(item.status)}</strong><small>{text(item.created_at)}</small><TechnicalDetails value={item} /></div>)}</section>
      <section><h3>任务团队</h3>{visible.teams.map(item => <div className="plan-node" key={text(item.id)}><strong>{statusLabel(item.status)} · 计划 {text(item.plan_revision)}</strong><small>{rows(asRecord(item.body).members).map(member => `${text(member.role_id)} / ${text(member.model_id)}`).join("、")}</small><TechnicalDetails value={item} /></div>)}
        {!terminal && <form onSubmit={event => { event.preventDefault(); try { const team = visible.teams.find(item => item.id === teamId); if (!team || !currentRuns.some(run => run.run_id === runId) || !reason.trim()) throw new Error("请选择已有团队、执行记录并说明原因。"); const proposal = teamReassignmentProposal(team.body, strategy); void act("保留角色、权限和预算，提出团队重新分配", `${questPath}/teams/reassign`, { ...version, run_id: runId, reason: reason.trim(), proposal }); } catch (error) { setError(errorMessage(error)); } }}>
          <label className="field-label">沿用的团队合约<select value={teamId} onChange={event => setTeamId(event.target.value)}><option value="">选择已有团队…</option>{visible.teams.map(item => <option key={text(item.id)} value={text(item.id)}>{text(item.id)} · {statusLabel(item.status)}</option>)}</select></label>
          <label className="field-label">需要重新分配的执行<select value={runId} onChange={event => setRunId(event.target.value)}><option value="">选择执行记录…</option>{currentRuns.map(run => <option key={run.run_id} value={run.run_id}>{run.role || run.run_id} · {statusLabel(run.state)}</option>)}</select></label>
          <label className="field-label">重新分配原因<input value={reason} maxLength={1000} onChange={event => setReason(event.target.value)} /></label>
          <label className="field-label">选型策略<select value={strategy} onChange={event => setStrategy(event.target.value)}><option value="greedy">综合能力</option><option value="single_model">单一模型</option><option value="coverage">能力覆盖</option><option value="complementarity">互补协作</option></select></label>
          <button type="submit" className="button" disabled={disabled || !teamId || !runId || !reason.trim()}>提出重新分配</button>
        </form>}
      </section>
      <details><summary>模型候选预览</summary><p className="notice">按模型库能力匹配的候选，仅供参考。</p>{visible.preview.map((item, index) => <div className="plan-node" key={text(item.role_id, String(index))}><strong>{text(item.role_name, text(item.role_id))}</strong>{rows(item.model_candidates).map((model, index) => <small key={index}>{text(model.provider)} / {text(model.model_id)} · 匹配 {text(model.fit_score)}</small>)}</div>)}</details>
      <details><summary>子智能体提案</summary>{visible.workers.map(item => <div className="plan-node" key={text(item.id)}><strong>{text(item.role)} · {statusLabel(item.status)}</strong><small>{text(item.model_id, "模型未指定")}</small></div>)}
        {!terminal && <form onSubmit={event => { event.preventDefault(); if (!role.trim()) return; const query = new URLSearchParams({ role: role.trim(), ...(model.trim() ? { model_id: model.trim() } : {}) }); void act("创建子智能体提案", `${questPath}/workers?${query}`); }}>
          <label className="field-label">角色<input value={role} maxLength={100} onChange={event => setRole(event.target.value)} /></label><label className="field-label">模型 ID（可选）<input value={model} maxLength={512} onChange={event => setModel(event.target.value)} /></label><button type="submit" className="button" disabled={disabled || !role.trim()}>创建提案</button>
        </form>}
      </details>
      {error && <p className="notice error" role="alert">{error}</p>}
    </div>
  </details>;
}

import { useCallback, useEffect, useLayoutEffect } from "react";
import { ApiError, request } from "../api";
import { appendUnique, errorMessage, preservedScrollTop, retainIfEqual } from "../logic";
import { messageMetadata } from "../timeline";
import { Row, TimelinePage, Page, Quest, QuestPage, TASK_VIEWS, eventKey, mergeEvents } from "../workspaceTypes";
import type { WorkspaceState } from "./useWorkspaceState";
import useWorkspacePreview from "./useWorkspacePreview";

export default function useConversationFeed(workspace: WorkspaceState & ReturnType<typeof useWorkspacePreview>) {
  const { connection, setConnection, coreSnapshot, setCoreSnapshot, setRestoreFenced, setRestoreStatus, view, messages, setMessages, timelineEvents, setTimelineEvents, timelineBefore, setTimelineBefore, setTimelineHasMore, setTimelineError, outgoing, setOutgoing, setHasNew, before, setBefore, setHasMore, historyBusy, setHistoryBusy, setConversationError, scrollRef, followBottom, historyAnchor, readingAnchor, seenMessages, seenEvents, seenInitialized, historyLoaded, questsLoaded, setQuests, questsBefore, setQuestsBefore, setQuestLoadError, setPendingApprovals, setApprovalLoadError, guard, previewOpen, previewWidth } = workspace;
  const refreshConversation = useCallback(async () => {
    if (!connection) return;
    const ticket = guard.start("conversation");
    try {
      const [page, questResult, approvals, settings, timeline, restored] = await Promise.all([
        request<Page>(connection, "/api/conversation?limit=100"),
        request<Quest[] | QuestPage>(connection, "/api/quests?limit=100")
          .then((value) => ({ value, error: "" }))
          .catch((error) => ({ value: null, error: errorMessage(error) })),
        request<{items: Row[]}>(connection, "/api/approvals/pending?limit=20")
          .then((value) => ({ value, error: "" }))
          .catch((error) => ({ value: { items: [] }, error: errorMessage(error) })),
        request<Row>(connection, "/api/settings").catch(() => null),
        request<TimelinePage>(connection, "/api/timeline?limit=100")
          .then((value) => ({ value, error: "" }))
          .catch((error) => ({ value: null, error: errorMessage(error) })),
        request<Row>(connection, "/api/restore-status").catch(() => null),
      ]);
      if (!guard.accepts(ticket)) return;
      const timelineElement = scrollRef.current;
      if (timelineElement?.getClientRects().length && !followBottom.current) {
        const viewport = timelineElement.getBoundingClientRect();
        const candidates = Array.from(timelineElement.querySelectorAll<HTMLElement>("[data-scroll-key]"))
          .map((element) => ({ element, bounds: element.getBoundingClientRect() }))
          .filter(({ bounds }) => bounds.height > 0 && bounds.bottom > viewport.top && bounds.top < viewport.bottom);
        const preferred = candidates.filter(({ element }) => !/^group(?:-files)?:/.test(element.dataset.scrollKey || ""));
        const anchor = (preferred.length ? preferred : candidates).sort((left, right) => Math.abs(left.bounds.top - viewport.top) - Math.abs(right.bounds.top - viewport.top))[0];
        readingAnchor.current = anchor ? { key: anchor.element.dataset.scrollKey!, offset: anchor.bounds.top - viewport.top, top: timelineElement.scrollTop } : null;
      }
      const fresh = page.messages.some((item) => !seenMessages.current.has(item.id)) ||
        !!timeline.value?.items.some((item) => !seenEvents.current.has(eventKey(item)));
      if (seenInitialized.current && fresh && !followBottom.current) setHasNew(true);
      page.messages.forEach((item) => seenMessages.current.add(item.id));
      timeline.value?.items.forEach((item) => seenEvents.current.add(eventKey(item)));
      seenInitialized.current = true;
      setMessages((existing) => retainIfEqual(existing, appendUnique(existing, page.messages || [])));
      if (timeline.value) setTimelineEvents((existing) => mergeEvents(existing, timeline.value!.items));
      setTimelineError(timeline.error);
      const committed = new Set(page.messages.map((item) => messageMetadata(item.metadata).request_id));
      setOutgoing((existing) => { const filtered = existing.filter((item) => !committed.has(item.requestId)); return filtered.length === existing.length ? existing : filtered; });
      if (!historyLoaded.current) { setBefore(page.next_before ?? null); setHasMore(!!page.has_more); }
      if (!historyLoaded.current && timeline.value) { setTimelineBefore(timeline.value.next_before ?? null); setTimelineHasMore(!!timeline.value.has_more); }
      if (questResult.value) {
        const questData = Array.isArray(questResult.value) ? questResult.value : questResult.value.items;
        setQuests((existing) => questsLoaded.current ? [...questData, ...existing.filter((item) => !questData.some((fresh) => fresh.id === item.id))] : questData);
        if (!questsLoaded.current) setQuestsBefore(Array.isArray(questResult.value) ? null : questResult.value.next_before ?? null);
      }
      setQuestLoadError(questResult.error);
      setPendingApprovals(approvals.value.items); setApprovalLoadError(approvals.error);
      setRestoreStatus(restored);
      setCoreSnapshot({ key: `${connection.base_url}|${connection.workspace_id || ""}|${connection.generation}`, settings: settings || {}, router: page.router || {} });
      setRestoreFenced(restored && typeof restored.fenced === "boolean" ? restored.fenced : settings && typeof settings.restore_fenced === "boolean" ? settings.restore_fenced : null);
      setConversationError("");
    } catch (error) {
      if (!guard.accepts(ticket)) return;
      setConversationError(errorMessage(error));
      if (error instanceof ApiError && error.status === 401) setConnection(null);
    }
  }, [connection, guard]);

  useEffect(() => {
    if (!connection) return;
    void refreshConversation();
    const timer = window.setInterval(() => void refreshConversation(), 6000);
    return () => window.clearInterval(timer);
  }, [connection, refreshConversation]);

  useLayoutEffect(() => {
    if (view !== "chat" && !TASK_VIEWS.includes(view)) return;
    const element = scrollRef.current;
