          .catch((error) => ({ value: null, error: errorMessage(error) })),
        request<{items: Row[]}>(connection, "/api/approvals/pending?limit=20")
          .then((value) => ({ value, error: "" }))
          .catch((error) => ({ value: { items: [] }, error: errorMessage(error) })),
