// Real browser File API + actual multi-page PDF bytes; Core events are labelled fixtures.
// Pane bounds/keyboard/reset: output/reference-native-layout/preview-source.txt (DUYS/FHYD).
async (page, { outputDir }) => {
  const checks = [], previewGeometry = [];
  let screenshots = 0;
  const check = (value, label) => { if (!value) throw new Error(label); checks.push(label); };
  const assertReadablePreview = async (preview, state, markdownVisible = false) => {
    const metrics = await preview.evaluate((panel) => {
      const size = (selector) => {
        const element = panel.querySelector(selector), style = getComputedStyle(element);
        return { font: parseFloat(style.fontSize), line: parseFloat(style.lineHeight), height: element.getBoundingClientRect().height };
      };
      return { viewport: innerWidth, previewWidth: panel.getBoundingClientRect().width, documentWidth: panel.querySelector('.preview-document').getBoundingClientRect().width, treeWidth: panel.querySelector('.preview-file-tree').getBoundingClientRect().width, tab: size('.preview-tab > [role="tab"]'), breadcrumb: size('.preview-breadcrumb'), toolbar: size('.preview-toolbar'), tree: size('.file-tree-row'), markdown: size('.file-markdown') };
    });
    previewGeometry.push({ state, ...metrics });
    check(metrics.tab.font === 14 && metrics.breadcrumb.font === 14, `${state}: preview tabs and breadcrumb use readable 14px UI text`);
    check(Math.abs(metrics.toolbar.height - 48) <= 1, `${state}: preview toolbar retains its 48px reading rhythm`);
    check(metrics.tree.font === 13 && Math.abs(metrics.tree.height - 30) <= 1, `${state}: file tree uses 13px text and 30px rows`);
    if (markdownVisible) check(metrics.markdown.font === 16 && metrics.markdown.line === 24, `${state}: Markdown uses 16px text with 24px line height`);
  };
  const shot = async (name) => { await page.mouse.move(0, 0); await page.waitForTimeout(220); await page.screenshot({ path: `${outputDir}/preview-${name}.png`, fullPage: true }); screenshots += 1; };
  const makePdf = () => {
    const objects = ['<< /Type /Catalog /Pages 2 0 R >>', '<< /Type /Pages /Kids [3 0 R 5 0 R] /Count 2 >>', '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 7 0 R >> >> /Contents 4 0 R >>'];
    const stream = (text) => { const value = `BT /F1 24 Tf 50 760 Td (${text}) Tj ET`; return `<< /Length ${value.length} >>\nstream\n${value}\nendstream`; };
    objects.push(stream('FORGE Preview - Page 1'), '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 7 0 R >> >> /Contents 6 0 R >>', stream('FORGE Preview - Page 2'), '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
    let pdf = '%PDF-1.4\n', offsets = [0];
    objects.forEach((object, index) => { offsets.push(Buffer.byteLength(pdf)); pdf += `${index + 1} 0 obj\n${object}\nendobj\n`; });
    const start = Buffer.byteLength(pdf); pdf += `xref\n0 8\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, '0')} 00000 n \n`).join('')}trailer\n<< /Size 8 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;
    return Buffer.from(pdf);
  };
  const markdown = '# FORGE 文件预览\n\n来自真实选择的文件。\n\n[打开源码](source.ts)\n\n[危险链接](javascript:alert(1))\n\n![外链图片](https://forbidden.invalid/image.png)\n\n<script>window.previewUnsafe=true</script>\n\n' + Array.from({ length: 90 }, (_, index) => `段落 ${index}：保留 Markdown 的阅读位置。\n`).join('\n');
  const code = Array.from({ length: 1200 }, (_, index) => `export const line${index} = "row ${index}";`).join('\n');
  let unsafeRequests = 0;
  page.on('request', (request) => { if (request.url().includes('forbidden.invalid')) unsafeRequests += 1; });
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('http://127.0.0.1:5173/');
  const opening = await page.evaluate(async () => {
    document.querySelector('[aria-label="查看工作空间文件"]').click();
    const samples = [], started = performance.now();
    do {
      await new Promise(requestAnimationFrame);
      samples.push(document.querySelector('.file-preview-workspace').getBoundingClientRect().width);
    } while (document.querySelector('.chat-workspace').style.getPropertyValue('--preview-progress') !== '1' && performance.now() - started < 800);
    return samples;
  });
  const preview = page.getByLabel('工作空间文件预览', { exact: true });
  await preview.getByRole('heading', { name: '工作空间文件' }).waitFor();
  check(await preview.isVisible(), 'preview opens on demand with a genuine browser import entry');
  check(opening.some((width) => width > 1 && width < opening.at(-1) - 1), `preview opening passes through intermediate measured widths: ${JSON.stringify(opening)}`);
  await page.getByLabel('消息内容', { exact: true }).fill('保留的草稿');
  const retainedConversation = await page.locator('.conversation-shell').elementHandle(), retainedDraft = await page.getByLabel('消息内容', { exact: true }).elementHandle();
  const pendingFileChooser = page.waitForEvent('filechooser');
  await preview.getByRole('button', { name: '打开文件', exact: true }).click();
  const fileChooser = await pendingFileChooser;
  check(fileChooser.isMultiple(), 'the tab plus button opens the real multi-file browser chooser');
  await fileChooser.setFiles([
    { name: 'README.md', mimeType: 'text/markdown', buffer: Buffer.from(markdown) },
    { name: 'source.ts', mimeType: 'text/plain', buffer: Buffer.from(code) },
    { name: 'report.pdf', mimeType: 'application/pdf', buffer: makePdf() },
    { name: 'legacy.txt', mimeType: 'text/plain', buffer: Buffer.from([0xff, 0xfe, 0x00, 0x00]) },
  ]);
  await preview.locator('.file-tree-row').filter({ hasText: 'README.md' }).click();
  await preview.locator('.file-markdown h1').waitFor();
  check(await preview.locator('.file-markdown h1').innerText() === 'FORGE 文件预览', 'Markdown renders the imported content');
  for (const width of [1440, 1280]) {
    await page.setViewportSize({ width, height: 900 });
    await page.waitForFunction(() => Math.abs(document.querySelector('.rail').getBoundingClientRect().width - 340) <= 1);
    await page.evaluate(() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))));
    await assertReadablePreview(preview, `split preview ${width}`, true);
    await shot(`markdown-split-${width}`);
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.waitForFunction(() => Math.abs(document.querySelector('.rail').getBoundingClientRect().width - 340) <= 1);
  check(await page.evaluate(() => !window.previewUnsafe), 'Markdown HTML does not execute');
  check(await preview.locator('.file-markdown img').count() === 0 && unsafeRequests === 0, 'Markdown never loads external images');
  check(await preview.locator('.file-markdown a[href^="javascript:"]').count() === 0, 'dangerous links are never rendered as anchors');
  await preview.locator('.document-rendered:visible').evaluate((element) => { element.scrollTop = 500; });
  const markdownScroll = await preview.locator('.document-rendered:visible').evaluate((element) => element.scrollTop);
  await preview.getByRole('button', { name: '查看源代码', exact: true }).click();
  check(await preview.locator('.source-line:visible').first().innerText() === '1\n# FORGE 文件预览', 'Markdown source is readable with line numbers');
  await preview.getByRole('button', { name: '预览', exact: true }).click();
  check(Math.abs(await preview.locator('.document-rendered:visible').evaluate((element) => element.scrollTop) - markdownScroll) <= 1, 'source/preview switching retains Markdown scroll');
  await preview.locator('.file-markdown').getByRole('button', { name: '打开源码', exact: true }).click();
  await preview.getByRole('tab', { name: 'source.ts', exact: true }).waitFor();
  await preview.getByLabel('source.ts 源码', { exact: true }).waitFor();
  check(await preview.getByRole('tab').count() === 2, 'relative document links open another tab in the same workspace');
  check(await preview.locator('.source-line:visible').count() <= 160, 'large source is virtualized');
  const sourceScroll = preview.getByLabel('source.ts 源码', { exact: true });
  await sourceScroll.evaluate((element) => { element.scrollTop = 10000; });
  await page.waitForTimeout(100);
  check(Number(await sourceScroll.locator('[data-line]').first().getAttribute('data-line')) > 300, 'virtual source reaches later lines');
  await preview.getByRole('tab', { name: 'README.md', exact: true }).click();
  await preview.getByRole('tab', { name: 'source.ts', exact: true }).click();
  check(Math.abs(await sourceScroll.evaluate((element) => element.scrollTop) - 10000) <= 1, 'tab switching preserves source reading position');
  check(await preview.getByLabel('在文件中查找', { exact: true }).filter({ visible: true }).count() === 0, 'source opens directly below the toolbar with file find controls collapsed');
  await preview.getByRole('button', { name: '查找文件内容', exact: true }).click();
  const fileFind = preview.getByLabel('在文件中查找', { exact: true }).filter({ visible: true });
  await fileFind.fill('line1199');
  await preview.getByLabel('下一个匹配', { exact: true }).filter({ visible: true }).click();
  await page.waitForTimeout(100);
  check(await sourceScroll.locator('[data-line="1200"]').count() === 1, 'source search locates a virtualized line');
  await preview.getByLabel('在文件中查找', { exact: true }).filter({ visible: true }).fill('export const');
  await preview.getByLabel('在文件中查找', { exact: true }).filter({ visible: true }).press('Enter');
  check(await sourceScroll.evaluate((element) => element.scrollTop) === 0, 'first search Enter goes to the first match');
  await sourceScroll.evaluate((element) => { element.scrollTop = 8000; });
  await fileFind.press('Escape');
  check(await fileFind.count() === 0, 'Escape closes the optional file find controls');
  await sourceScroll.focus();
  await page.keyboard.press('Control+f');
  await fileFind.waitFor();
  check(await fileFind.evaluate((element) => document.activeElement === element) && await fileFind.inputValue() === '', 'Ctrl+F opens and focuses the existing file find input with its cleared query');
  await fileFind.press('Escape');
  check(Math.abs(await sourceScroll.evaluate((element) => element.scrollTop) - 8000) <= 1, 'opening and closing file find preserves the source reading position');
  await preview.getByRole('button', { name: '重新读取文件', exact: true }).click();
  await page.waitForTimeout(100);
  check(Math.abs(await sourceScroll.evaluate((element) => element.scrollTop) - 8000) <= 1, 'refresh keeps the source reading position');
  await preview.locator('.file-tree-row').filter({ hasText: 'source.ts' }).click();
  check(await preview.getByRole('tab').count() === 2, 'reopening a file reuses its tab');
  await shot('code-light');
  const divider = page.getByRole('separator', { name: '调整文件预览宽度' });
  const initialPreviewWidth = Number(await divider.getAttribute('aria-valuenow'));
  await divider.focus(); await divider.press('ArrowLeft');
  const keyboardPreviewWidth = Number(await divider.getAttribute('aria-valuenow'));
  check(keyboardPreviewWidth === Math.min(initialPreviewWidth + 10, Number(await divider.getAttribute('aria-valuemax'))), 'native splitter resizes in 10px keyboard steps within pixel bounds');
  const bounds = await divider.boundingBox();

